  ));
    ELSE
      PERFORM __mj."spCreateTemplateContent"(p_ID := p_ID_fcbeb6bcfc70, p_TemplateID := p_TemplateID_fcbeb6bcfc70, p_TypeID := p_TypeID_fcbeb6bcfc70, p_TemplateText := p_TemplateText_fcbeb6bcfc70, p_Priority := p_Priority_fcbeb6bcfc70, p_IsActive := p_IsActive_fcbeb6bcfc70);
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
