  ));
    ELSE
      PERFORM __mj."spCreateTemplateContent"(p_ID := p_ID_f6045d3699bc, p_TemplateID := p_TemplateID_f6045d3699bc, p_TypeID := p_TypeID_f6045d3699bc, p_TemplateText := p_TemplateText_f6045d3699bc, p_Priority := p_Priority_f6045d3699bc, p_IsActive := p_IsActive_f6045d3699bc);
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = '__mj' AND p.proname = 'spUpdateTemplateContent'
         AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
