    'TemplateID', p_TemplateID_d9c30092f6ed,
    'TypeID', p_TypeID_d9c30092f6ed,
    'TemplateText', p_TemplateText_d9c30092f6ed,
    'Priority', p_Priority_d9c30092f6ed,
    'IsActive', p_IsActive_d9c30092f6ed,
    'ID', p_ID_d9c30092f6ed
  ));
  ELSE
    PERFORM __mj."spUpdateTemplateContent"(p_TemplateID := p_TemplateID_d9c30092f6ed, p_TypeID := p_TypeID_d9c30092f6ed, p_TemplateText := p_TemplateText_d9c30092f6ed, p_Priority := p_Priority_d9c30092f6ed, p_IsActive := p_IsActive_d9c30092f6ed, p_ID := p_ID_d9c30092f6ed);
  END IF;
END $mj$;

