    /** Pins the model. */
    ModelID?: string;
    /** LLM: runs the rubric this many times and keeps each criterion''s median level. */
    Samples?: number;
    Mode?: ''SinglePass'' | ''PerCriterion'';
    /** Settings for a custom evaluator, keyed by its evaluator name. */
    Extensions?: Record<string, JsonValue>;
}
