BEGIN
  p_ID_f579a47d402f := 'FACEE516-41BD-4346-BB6F-07F44CF97E2F';
  p_Name_f579a47d402f := 'Discard Work Queue Delivery';
  p_OperationKey_f579a47d402f := 'WorkQueue.DiscardDelivery';
  p_CategoryID_f579a47d402f := '826B85CB-BE74-4716-94A3-1126DBED59AD';
  p_Description_f579a47d402f := 'Resolves one delivery without processing it, with a required reason. A pending or dead-lettered delivery becomes Discarded immediately; discarding a dead-lettered Ordered head unblocks its key. An in-flight delivery is cancelled instead (cancelRequested = true): the running handler is told to stop within one heartbeat interval (30 s at most) and the delivery becomes Discarded as soon as the handler acknowledges, or at lease expiry if its worker is gone. Implemented by WorkQueueDiscardDeliveryServerOperation in @memberjunction/work-queue-engine.';
  p_InputTypeName_f579a47d402f := 'WorkQueueDiscardDeliveryInput';
  p_InputTypeDefinition_f579a47d402f := '/** Input for `WorkQueue.DiscardDelivery`. */
export interface WorkQueueDiscardDeliveryInput {
    subscriptionName: string;
    /** A pending, dead-lettered or in-flight delivery. */
    deliveryID: string;
    /** Why the work is being dropped. Required; at most 1000 characters. */
    reason: string;
}
';
  p_InputTypeIsArray_f579a47d402f := FALSE;
  p_OutputTypeName_f579a47d402f := 'WorkQueueDiscardDeliveryOutput';
  p_OutputTypeDefinition_f579a47d402f := '/** Output of `WorkQueue.DiscardDelivery`. */
export interface WorkQueueDiscardDeliveryOutput {
    /** False when the transport cannot discard this kind of delivery (for example any SQS message). */
    supported: boolean;
    /** True when the delivery is now Discarded, or (for an in-flight delivery) its cancel was recorded. */
    discarded: boolean;
    /**
     * True when the delivery was in flight: CancelRequestedAt is set, the running handler''s next heartbeat (30 s at
     * most) aborts it with reason ''Cancelled'', and the row becomes Discarded when the handler acknowledges — or at
     * lease expiry if its worker is gone (03 §7).
     */
    cancelRequested: boolean;
}
';
  p_OutputTypeIsArray_f579a47d402f := FALSE;
  p_ExecutionMode_f579a47d402f := 'Sync';
  p_RequiredScope_f579a47d402f := 'workqueue:operate';
