    /** Deliveries currently leased by a worker. */
    inFlight: number;
    /** claimable + inFlight — the value a scheduler should scale on. */
    total: number;
    /** True when either count hit its cap of 1000: the real backlog is at least this large. */
    capped: boolean;
}
